import { useEffect, useState, useRef, useCallback } from "react";
import {
  Button,
  Grid,
  IconButton,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import TablePlan from "src/views/tables/IT-Solution-Overview/TablePlan";
import DialogPlan from "src/views/dialog/IT-Solution-Overview/DialogPlan";
import DialogViewPlanInfo from "src/views/dialog/IT-Solution-Overview/DialogViewPlanInfo";
import DialogFeatures from "src/views/dialog/IT-Solution-Features/DialogFeatures";
import DialogOverviewFeatures from "src/views/dialog/IT-Solution-Overview/DialogOverviewFeatures";
import TableOverviewFeatures from "src/views/tables/IT-Solution-Overview/TableOverviewFeatures";
import DialogOverviewFeaturesTitle from "src/views/dialog/IT-Solution-Overview/DialogOverviewFeaturesTitle";
import TableOverviewFeaturesTitle from "src/views/tables/IT-Solution-Overview/TableOverviewFeaturesTitle";

const ITSolutionOverviewFeaturesTitle = () => {
  const navigate = useNavigate();
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [overViewFeaturesData, setOverViewFeaturesData] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("");

  const { id } = useParams(); // Get id from location.state

  // Testimonials
  const [overViewFeaturesDialogOpen, setOverViewFeaturesDialogOpen] =
    useState(false);
  const [overViewFeaturesDialogMode, setOverViewFeaturesDialogMode] =
    useState("add");
  const [clientCategoryToEdit, setClientCategoryToEdit] = useState(null);
  const [contactViewFormDialogOpen, setContactViewFormDialogOpen] =
    useState(false);
  const [contactToEdit, setContactToEdit] = useState(null);
  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [testimonialToDelete, setTestimonialToDelete] = useState(null);

  const toggleRugFormDialog = (
    e,
    mode = "add",
    clientCategoryToEdit = null
  ) => {
    setOverViewFeaturesDialogOpen((prev) => !prev);
    setOverViewFeaturesDialogMode(mode);
    setClientCategoryToEdit(clientCategoryToEdit);
  };

  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setTestimonialToDelete(dataToDelete);
  };
  const toggleContactViewFormDialog = (e, contactToEdit = null) => {
    setContactViewFormDialogOpen((prev) => !prev);
    setContactToEdit(contactToEdit);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionOverviewFeaturesTitle.list(id), { params })
      .then((response) => {
        console.log(response.data.data);
        setOverViewFeaturesData(response.data.data);
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      axiosInstance
        .delete(
          ApiEndPoints.ITSolutionOverviewFeaturesTitle.delete(
            testimonialToDelete.id
          )
        )
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
            search: search,
          });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, testimonialToDelete, pageSize, search]
  );
  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text="Overview Features Title" />
            </Typography>
          }
          action={
            <Button variant="contained" onClick={toggleRugFormDialog}>
              Add Features Title
            </Button>
          }
        />
        <Grid item xs={12}>
          <Card>
            {/* <Box
              sx={{
                p: 5,
                pb: 0,
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                justifyContent: "end",
              }}
            >
              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  gap: 5,
                }}
              >
                <Select
                  size="small"
                  defaultValue={" "}
                  sx={{ bgcolor: "#F7FBFF" }}
                  onChange={(e) => {
                    const selectedValue = e.target.value;
                    setStatus(selectedValue === "All" ? "" : selectedValue);
                  }}
                >
                  <MenuItem disabled value={" "}>
                    <em>Status</em>
                  </MenuItem>
                  <MenuItem value={"All"}>All</MenuItem>
                  <MenuItem value={"active"}>Active</MenuItem>
                  <MenuItem value={"inactive"}>Inactive</MenuItem>
                </Select>
                <TextField
                  type="search"
                  size="small"
                  placeholder="Search"
                  onChange={handleSearchChange}
                />
              </Box>
            </Box> */}
            <Box sx={{ p: 5 }}>
              <TableOverviewFeaturesTitle
                search={search}
                loading={loading}
                rows={overViewFeaturesData}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleDelete={toggleConfirmationDialog}
                toggleEdit={toggleRugFormDialog}
                toggleView={toggleContactViewFormDialog}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>
      <DialogOverviewFeaturesTitle
        mode={overViewFeaturesDialogMode}
        open={overViewFeaturesDialogOpen}
        toggle={toggleRugFormDialog}
        // itSolutionOverviewId={overViewId}
        dataToEdit={clientCategoryToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Overview Feature's Title"
        subtitle="Are you sure you want to delete this Overview Feature?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ITSolutionOverviewFeaturesTitle;
