import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  InputAdornment,
  Radio,
  RadioGroup,
  TextField,
  Typography,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import { useParams } from "react-router-dom";

const validationSchema = yup.object().shape({
  title: yup
    .string()
    .trim()
    .required("Please Add a Title.")
    .max(50, "Title must be at most 50 characters."),
  sub_title: yup
    .string()
    .trim()
    .required("Please Add a Sub Title.")
    .max(80, "Sub Title must be at most 80 characters."),
});

const DialogPlan = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess } = props;
  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");
  const [overviewPlan, setOverviewPlan] = useState([]);
  const [overviewPlanInput, setOverviewPlanInput] = useState("");
  const { id } = useParams();
  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm({
    defaultValues: {
      title: "",
      sub_title: "",
      descriptions: [],
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });
  const handleAddOverviewPlan = () => {
    if (overviewPlanInput.trim()) {
      setOverviewPlan([...overviewPlan, { text: overviewPlanInput.trim() }]);
      setOverviewPlanInput("");
    }
  };

  const handleDeleteOverviewPlan = (overviewPlanToDelete) => {
    setOverviewPlan((prevOverviewPlan) =>
      prevOverviewPlan.filter(
        (overviewPlan, index) => index !== overviewPlanToDelete
      )
    );
  };
  const handleDeleteEditOverviewPlan = (planToDelete) => {
    console.log(planToDelete);

    axiosInstance
      .delete(
        ApiEndPoints.ITSolutionOverviewPlan.deleteOverviewPlan(planToDelete.id)
      )
      .then((response) => response.data)
      .then((response) => {
        setOverviewPlan((prevPlan) =>
          prevPlan.filter((plan) => plan.id !== planToDelete.id)
        );
        toastSuccess(response.message);
      })
      .catch((error) => {
        toastError(error);
      });
  };
  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(
        mode === "add" ? "Add Overview Plan" : "Edit Overview Plan"
      );
      if (mode === "edit") {
        setOverviewPlan(dataToEdit?.descriptions);
      }
      reset({
        title: dataToEdit?.title || "",
        sub_title: dataToEdit?.sub_title || "",
        descriptions: dataToEdit?.descriptions || [],
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = (data) => {
    let payload = {
      title: data.title,
      sub_title: data.sub_title,
      sub_it_solution_list_id: id,
      descriptions: overviewPlan,
    };

    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ITSolutionOverviewPlan.edit(dataToEdit.id),
        payload,
        {}
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.ITSolutionOverviewPlan.create,
        payload,
        {}
      );
    }
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
        setOverviewPlan([]);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const toggleDialog = () => {
    toggle();
    setOverviewPlan([]);
  };
  return (
    <>
      <Dialog open={open} fullWidth maxWidth="sm" scroll="paper">
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggleDialog}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="hub-address-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="title"
                    error={Boolean(errors.title)}
                  >
                    Title
                  </FormLabel>
                  <Controller
                    name="title"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter title"
                        onChange={onChange}
                        id="title"
                        value={value}
                        error={Boolean(errors.title)}
                      />
                    )}
                  />
                  {errors.title && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.title.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>

              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="sub_title"
                    error={Boolean(errors.sub_title)}
                  >
                    Sub Title
                  </FormLabel>
                  <Controller
                    name="sub_title"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Sub Title"
                        onChange={onChange}
                        id="sub_title"
                        value={value}
                        error={Boolean(errors.sub_title)}
                      />
                    )}
                  />
                  {errors.sub_title && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.sub_title.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>

              <Grid item xs={12} pb={3}>
                <FormControl fullWidth error={Boolean(errors.overviewPlan)}>
                  <FormLabel
                    htmlFor="descriptions"
                    error={Boolean(errors.descriptions)}
                  >
                    Plan Description
                  </FormLabel>
                  {/* <Controller
                    name="descriptions"
                    control={control}
                    defaultValue=""
                    rules={{
                      validate: () => {
                        if (overviewPlan.length === 0) {
                          return "Please add at least one plan description.";
                        }
                        return true;
                      },
                    }}
                    render={({
                      field: { value, onChange },
                      fieldState: { error },
                    }) => (
                      <TextField
                        type="text"
                        variant="standard"
                        onChange={(e) => {
                          onChange(overviewPlan);
                          setOverviewPlanInput(e.target.value);
                        }}
                        id="descriptions"
                        value={overviewPlanInput}
                        InputProps={{
                          endAdornment: (
                            <InputAdornment position="end">
                              <IconButton
                                disableRipple
                                onClick={handleAddOverviewPlan}
                              >
                                <Typography
                                  fontWeight={700}
                                  color={"#602de1c2"}
                                >
                                  Add
                                </Typography>
                              </IconButton>
                            </InputAdornment>
                          ),
                          
                        }}
                       
                      />
                     
                    )}
                   
                  /> */}
                  <Controller
                    name="descriptions"
                    control={control}
                    defaultValue=""
                    rules={{
                      validate: () => {
                        if (overviewPlan.length === 0) {
                          return "Please add at least one plan description.";
                        }
                        return true;
                      },
                    }}
                    render={({
                      field: { value, onChange },
                      fieldState: { error },
                    }) => (
                      <>
                        <TextField
                          type="text"
                          variant="outlined"
                          placeholder="Add Plan Description"
                          onChange={(e) => {
                            onChange(e.target.value); // Set value for validation
                            setOverviewPlanInput(e.target.value); // Update local state
                          }}
                          id="descriptions"
                          value={overviewPlanInput}
                          InputProps={{
                            endAdornment: (
                              <InputAdornment position="end">
                                <IconButton
                                  disableRipple
                                  onClick={handleAddOverviewPlan}
                                >
                                  <Typography
                                    fontWeight={700}
                                    color={"#602de1c2"}
                                  >
                                    Add
                                  </Typography>
                                </IconButton>
                              </InputAdornment>
                            ),
                          }}
                        />
                        {error && (
                          <Typography color="error" variant="caption">
                            {error.message}
                          </Typography>
                        )}
                      </>
                    )}
                  />
                </FormControl>
              </Grid>
              {overviewPlan.length > 0 && (
                <Grid item xs={12}>
                  <Box
                    sx={{
                      display: "flex",
                      flexDirection: "column",
                      gap: 1,
                      border: "1px solid #ccc",
                      my: 3,
                      py: 2,
                      px: 3,
                      borderRadius: "5px",
                      width: "100%",
                    }}
                  >
                    {overviewPlan?.map((plan, index) => (
                      <Box
                        sx={{
                          display: "flex",
                          alignItems: "end",
                          justifyContent: "space-between",
                          gap: 3,
                          flexGrow: 1,
                        }}
                        key={index}
                      >
                        <Typography
                          sx={{
                            fontSize: "14px",
                          }}
                        >
                          {index + 1}. {plan.text}
                        </Typography>
                        <IconButton
                          onClick={() =>
                            mode === "edit"
                              ? handleDeleteEditOverviewPlan(plan)
                              : handleDeleteOverviewPlan(index)
                          }
                        >
                          {" "}
                          <CloseIcon
                            sx={{
                              fontSize: "16px",
                              color: "#602de1c2",
                            }}
                          />
                        </IconButton>
                      </Box>
                    ))}
                  </Box>
                </Grid>
              )}
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="hub-address-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogPlan;
